{"script":"() => {
  const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
  const results = [];
  cards.forEach(card => {
    const title = card.querySelector('span')?.innerText || '';
    const ratingsText = card.querySelector('[id^="mntl-recipe-card-meta"]')?.innerText || '';
    const starsContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
    let ratingValue = '';
    if (starsContainer) {
      // Try to find the rating value
      const ratingSpan = starsContainer.querySelector('.mntl-recipe-card-meta__rating-number');
      if (ratingSpan) ratingValue = ratingSpan.innerText;
      // Check aria-label
      const ariaLabel = starsContainer.getAttribute('aria-label') || '';
      ratingValue = ratingValue || ariaLabel;
    }
    results.push({
      title: title,
      meta: ratingsText,
      starsInfo: ratingValue
    });
  });
  return results;
}"}

